# ==============================================================================
# LTAP SYNTHETIC SAMPLING & DATA BALANCING — VERSION 1.0 (STANDALONE)
# Laboratorio de Tecnologia Analitica de Processos (LTAP / UERJ)
#
# Standalone RStudio Single-File Launcher:
# Automatically checks for, installs, and loads all required CRAN dependencies
# so that any user can open this single file in RStudio, click 'Run App', and
# immediately access 100% of Version 01 functionality without prior setup.
# ==============================================================================

local({
  pkgs <- c(
    "shiny", "shinyjs", "shinydashboard", "shinyWidgets", "shinycssloaders",
    "DT", "plotly", "ggplot2", "readxl", "writexl", "openxlsx", "tibble",
    "dplyr", "tidyr", "purrr", "reshape2", "RColorBrewer", "ellipse",
    "smotefamily", "imbalance", "UBL", "scutr", "caret", "skimr",
    "rrcov", "mdatools", "Rtsne", "car", "robustbase", "philentropy",
    "Hotelling", "vegan", "MVN", "rgl", "reticulate", "later", "MASS"
  )
  installed <- rownames(installed.packages())
  missing_pkgs <- pkgs[!pkgs %in% installed]
  if (length(missing_pkgs) > 0) {
    message("[LTAP Synthetic Sampling V1] Installing missing dependencies: ", paste(missing_pkgs, collapse = ", "))
    tryCatch(
      install.packages(missing_pkgs, repos = "https://cloud.r-project.org", quiet = TRUE),
      error = function(e) message("Auto-install warning: ", e$message)
    )
  }
  for (p in pkgs) {
    suppressPackageStartupMessages(try(library(p, character.only = TRUE), silent = TRUE))
  }
})

# --- LTAP TEMPDIR GUARDIAN & WATCHDOG (Anti-AV / OS Temp Cleanup) ---
local({
  td <- tempdir(check = FALSE)
  if (!dir.exists(td)) try(dir.create(td, recursive = TRUE, showWarnings = FALSE), silent = TRUE)
  if (requireNamespace("later", quietly = TRUE)) {
    .ltap_tempdir_watchdog <<- function() {
      td <- tempdir(check = FALSE)
      if (!dir.exists(td)) {
        try(dir.create(td, recursive = TRUE, showWarnings = FALSE), silent = TRUE)
      }
      later::later(.ltap_tempdir_watchdog, delay = 30)
    }
    later::later(.ltap_tempdir_watchdog, delay = 10)
  }
})
