# ========================================================
# LTAP SYNTHETIC SAMPLING & BALANCING — VERSION 1.0
# Laboratorio de Tecnologia Analitica de Processos (LTAP / UERJ)
# ========================================================

# Set English locale and language
Sys.setenv(LANGUAGE = "en")
try(Sys.setlocale("LC_MESSAGES", "C"), silent = TRUE)

# Ensure shiny::validate and shiny::need are never masked by other packages
validate <- shiny::validate
need <- shiny::need

# --- ROBUST PYTHON DEPENDENCY DECLARATION ---
if (requireNamespace("reticulate", quietly = TRUE)) {
  tryCatch({
    reticulate::py_require(c("scikit-learn", "imbalanced-learn", "smote-variants", "numpy", "pandas"))
  }, error = function(e) NULL)
}

# --- ROBUST CROSS-PLATFORM PYTHON / RETICULATE INITIALIZER ---
.ltap_init_python <- function() {
  if (!requireNamespace("reticulate", quietly = TRUE)) return(FALSE)
  
  # 1. Desktop Portable Python (Windows)
  candidates <- c(
    file.path("Python-Portable", "python.exe"),
    file.path("..", "Python-Portable", "python.exe"),
    file.path("../..", "Python-Portable", "python.exe"),
    file.path(getwd(), "Python-Portable", "python.exe")
  )
  for (cand in candidates) {
    if (file.exists(cand)) {
      tryCatch({
        reticulate::use_python(normalizePath(cand), required = FALSE)
        if (reticulate::py_available(initialize = TRUE)) return(TRUE)
      }, error = function(e) NULL)
    }
  }
  
  # 2. Virtualenv "r-reticulate"
  tryCatch({
    if (reticulate::virtualenv_exists("r-reticulate")) {
      reticulate::use_virtualenv("r-reticulate", required = FALSE)
      if (reticulate::py_available(initialize = TRUE)) return(TRUE)
    }
  }, error = function(e) NULL)
  
  # 3. Discover / initialize Python
  tryCatch({
    reticulate::py_discover_config()
    return(reticulate::py_available(initialize = TRUE))
  }, error = function(e) FALSE)
}

.ltap_get_py_module <- function(mod_name) {
  tryCatch({
    if (!requireNamespace("reticulate", quietly = TRUE)) return(NULL)
    .ltap_init_python()
    reticulate::import(mod_name, delay_load = TRUE)
  }, error = function(e) NULL)
}

