    tags$head(
      tags$style(HTML("
        /* Global Chemometrics Computation Banner */
        #cwa-busy-banner {
          position: fixed;
          top: 12px;
          right: 70px;
          z-index: 100000;
          background: rgba(15, 23, 42, 0.95);
          color: #38bdf8;
          padding: 8px 18px;
          border-radius: 24px;
          box-shadow: 0 4px 20px rgba(0,0,0,0.4);
          font-weight: 600;
          font-size: 13px;
          letter-spacing: 0.4px;
          display: none;
          align-items: center;
          gap: 10px;
          border: 1px solid rgba(56, 189, 248, 0.5);
          pointer-events: none;
        }
        html.shiny-busy #cwa-busy-banner {
          display: flex !important;
        }
        .cwa-spinner {
          width: 16px;
          height: 16px;
          border: 2px solid rgba(56, 189, 248, 0.25);
          border-top-color: #38bdf8;
          border-radius: 50%;
          animation: cwa-spin 0.75s linear infinite;
        }
        @keyframes cwa-spin {
          to { transform: rotate(360deg); }
        }
      ")),
