      tabItem(
        tabName = "smote",
        h2("SMOTE"),
        fluidRow(
          box(
            title = h3("SMOTE Parameters"),
            width = 4,
            status = "primary",
            numericInput('K', 'Number of nearest neighbors during sampling process (k_neighbors):', 
                         value = 3, min = 1, max = Inf, step = 1),
            numericInput('dup_size', 'Maximum times of synthetic minority instances over majority instances:', 
                         value = 1, min = 1, max = Inf, step = 1),
            shiny::hr(),
            uiOutput("target"),
            uiOutput("class_in"),
            checkboxInput("smote_all_classes", "Perform SMOTE on the entire dataset", value = FALSE),
            p(strong("Note: For datasets with quantitative (numeric) variables, choose SMOTE.")),
            actionButton("runSMOTE", "Run SMOTE", class = "btn-block btn-success"),
            actionButton("confirmSMOTE", "Confirm SMOTE", class = "btn-block btn-success")
          ),
          box(
            title = h3("Synthetic Data Overview"), 
            width = 8, 
            status = "primary", 
            tabsetPanel(
              tabPanel("SMOTE Summary", verbatimTextOutput("summary_gen")),
              tabPanel("Generated Data", tableOutput("gen_table")),
              tabPanel("Class Frequency Barplot", plotlyOutput("barplot_SMOTE"))
            )
          )
        )
      ),
      
      tabItem(
        tabName = "smote_nc",
