            numericInput('K_nc', 'Number of nearest neighbors during sampling process (k_neighbors):', 
                         value = 3, min = 1, max = Inf, step = 1),
            selectInput(
              inputId = "smote_sampling_strategy",
              label = "Sampling Strategy (sampling_strategy):",
              choices = c(
                "minority" = "minority",
                "not minority" = "not minority",
                "not majority" = "not majority",
                "all" = "all",
                "auto" = "auto"
              ),
              selected = "auto"
            ),
            p(strong("Choose how classes should be balanced:"), " "),
            p(strong(".minority"), em("only the minority class will be augmented;")),
            p(strong(".not minority"), em("all classes except the minority class;")),
            p(strong(".not majority"), em("all classes except the majority class;")),
            p(strong(".all"), em("all classes;")),
            p(strong(".auto"), em("equivalent to 'not majority'.")),
            shiny::hr(),
            uiOutput("target_nc"),
            p(strong("Note: For datasets with both quantitative (numeric) and qualitative (categorical) variables, use SMOTE-NC.")),
