                "not minority" = "not minority",
                "not majority" = "not majority"
              ),
              selected = "auto"
            ),
            
            p(strong("Choose how classes should be handled during removal:"), " "),
            p(strong(".auto"), em("removes majority class samples forming Tomek pairs;")),
