        t <- list(
          family = "times",
          size = 12,
          color = toRGB("black"))
        
        plot_ly(type="scatter",
                x=1:length(variance),
                y=variance,
                mode="lines+markers",
                showlegend=F,
                text=paste("Component ", 1:length(variance), sep=""),
                hoverinfo="text y")%>%
          layout(title="<b>Variance</b>",
