  # Importando RandomOverSampler corretamente
  
  RandomOverSampler <- function(...) { mod <- .ltap_get_py_module("imblearn.over_sampling"); if (!is.null(mod)) mod$RandomOverSampler(...) else NULL }
  
  # Reactive para armazenar o resultado do Random Upsampling
  
  RU_Data <- reactiveVal(NULL)
  runRU <- reactiveVal(FALSE)
  
  # UI: Seleção do alvo
  
  output$target_ru <- renderUI({
    df <- filedata()
    if (is.null(df)) return(NULL)
    items <- names(df)
    names(items) <- items
    selectInput("target_ru",
                "Target class attribute column in dataset:",
                items)
  })
  
  # Executando o Random Upsampling
  
  observeEvent(input$runRU, {
    runSMOTE(FALSE)
    runSMOTENC(FALSE)
    runBorderlineSMOTE(FALSE)
    runSVM_SMOTE(FALSE)
    runADASYN(FALSE)
