  EditedNearestNeighbours <- function(...) { mod <- .ltap_get_py_module("imblearn.under_sampling"); if (!is.null(mod)) mod$EditedNearestNeighbours(...) else NULL }
  
  # Reactive para armazenar o resultado do ENN
  
  ENN_Data <- reactiveVal(NULL)
  runENN <- reactiveVal(FALSE)
  
  # UI: Seleção do alvo
  
