      return()
    }
    
    rus <- RandomUnderSampler(
      sampling_strategy = input$rd_sampling_strategy,
      random_state = as.integer(input$rd_random_state),
      replacement = input$rd_replacement
    )
    
    if (is.null(rus)) {
      showNotification("Python module 'imbalanced-learn' is not available. Please verify Python configuration or use R-native methods.", type = "error")
      return()
