      plotlyOutput("class_dist_tl", height = "500px")
    } else if (isTRUE(runSMOTEENN())) {
      plotlyOutput("class_dist_smotenn", height = "500px")
    } else if (isTRUE(runSMOTEIPF())) { #ADICIONADO EM 13/07/2025
