    #############BLOCO MODIFICADO EM 20/06/2025
    
    if (isTRUE(runTomek())) {
      smote_data$class <- paste(smote_data$class, "Removed")
    } else if (isTRUE(runNearMiss())) {
      smote_data$class <- paste(smote_data$class, "Removed")
    } else if (isTRUE(runENN())) {
      smote_data$class <- paste(smote_data$class, "Removed") 
    } else if (isTRUE(runOSS())) {
      smote_data$class <- paste(smote_data$class, "Removed") 
   } else if (isTRUE(runRD())) {
