  # =========================================================================
  
  # =========================================================================
  
  # =========================================================================
  # UNIFIED RESAMPLING DATA EXTRACTION HELPER (ALL 16 METHODS)
  # =========================================================================
  
  get_active_resampled_data <- reactive({
    req(filedata())
    orig <- as.data.frame(filedata())
    
    syn_data <- NULL
    rem_data <- NULL
    target_col <- NULL
    method_name <- "Original"
    
    if (isTRUE(runSMOTETL()) && !is.null(SMOTETL_Data())) {
      syn_data <- SMOTETL_Data()$syn_data; rem_data <- SMOTETL_Data()$removed_data; target_col <- input$target_tl; method_name <- "SMOTE-TL"
    } else if (isTRUE(runSMOTEENN()) && !is.null(SMOTEENN_Data())) {
      syn_data <- SMOTEENN_Data()$syn_data; rem_data <- SMOTEENN_Data()$removed_data; target_col <- input$target_enn2; method_name <- "SMOTE-ENN"
    } else if (isTRUE(runSMOTEIPF()) && !is.null(SMOTEIPF_Data())) {
      syn_data <- SMOTEIPF_Data()$syn_data; rem_data <- SMOTEIPF_Data()$removed_data; target_col <- input$target_ipf; method_name <- "SMOTE-IPF"
    } else if (isTRUE(runSPIDER()) && !is.null(SPIDER_Data())) {
      syn_data <- SPIDER_Data()$syn_data; rem_data <- SPIDER_Data()$removed_data; target_col <- input$target_spider; method_name <- "SPIDER"
    } else if (isTRUE(runTomek()) && !is.null(Tomek_Data())) {
      rem_data <- Tomek_Data()$removed_data; target_col <- input$target_tomek; method_name <- "Tomek Links"
    } else if (isTRUE(runNearMiss()) && !is.null(NearMiss_Data())) {
      rem_data <- NearMiss_Data()$removed_data; target_col <- input$target_nearmiss; method_name <- "NearMiss"
    } else if (isTRUE(runENN()) && !is.null(ENN_Data())) {
      rem_data <- ENN_Data()$removed_data; target_col <- input$target_enn; method_name <- "ENN"
    } else if (isTRUE(runOSS()) && !is.null(OSS_Data())) {
      rem_data <- OSS_Data()$removed_data; target_col <- input$target_oss; method_name <- "OSS"
    } else if (isTRUE(runRD()) && !is.null(RD_Data())) {
      rem_data <- RD_Data()$removed_data; target_col <- input$target_rd; method_name <- "Random Downsampling"
    } else if (isTRUE(runSBC()) && !is.null(SBC_Data())) {
      rem_data <- SBC_Data()$removed_data; target_col <- input$target_sbc; method_name <- "Sub-Class Balance"
    } else if (isTRUE(runSMOTENC()) && !is.null(SMOTENC_Data())) {
      syn_data <- SMOTENC_Data()$syn_data; target_col <- input$target_nc; method_name <- "SMOTE-NC"
    } else if (isTRUE(runBorderlineSMOTE()) && !is.null(BorderlineSMOTE_Data())) {
      syn_data <- BorderlineSMOTE_Data()$syn_data; target_col <- input$target_borderline; method_name <- "Borderline-SMOTE"
    } else if (isTRUE(runSVM_SMOTE()) && !is.null(SVM_SMOTE_Data())) {
      syn_data <- SVM_SMOTE_Data()$syn_data; target_col <- input$target_svm; method_name <- "SVM-SMOTE"
    } else if (isTRUE(runADASYN()) && !is.null(ADASYN_Data())) {
      syn_data <- ADASYN_Data()$syn_data; target_col <- input$target_adasyn; method_name <- "ADASYN"
    } else if (isTRUE(runRU()) && !is.null(RU_Data())) {
      syn_data <- RU_Data()$syn_data; target_col <- input$target_ru; method_name <- "Random Upsampling"
    } else if (isTRUE(runSMOTE()) && !is.null(SMOTE_Data())) {
      syn_data <- SMOTE_Data()$syn_data; target_col <- input$target; method_name <- "SMOTE"
    }
    
    if (is.null(target_col) || !(target_col %in% names(orig))) {
      if ("class" %in% names(orig)) target_col <- "class"
      else if ("sampleclass" %in% names(orig)) target_col <- "sampleclass"
      else if ("sampleclass.." %in% names(orig)) target_col <- "sampleclass.."
      else target_col <- names(orig)[1]
    }
    
    orig$classe_base <- as.character(orig[[target_col]])
    orig$Tipo <- "Original"
    
    if (!is.null(syn_data) && nrow(syn_data) > 0) {
      if (target_col %in% names(syn_data)) syn_data$classe_base <- as.character(syn_data[[target_col]])
      else if ("class" %in% names(syn_data)) syn_data$classe_base <- as.character(syn_data$class)
      else syn_data$classe_base <- as.character(syn_data[[1]])
      syn_data$Tipo <- "Synthetic"
    } else {
      syn_data <- orig[0, , drop = FALSE]
    }
    
    if (!is.null(rem_data) && nrow(rem_data) > 0) {
      if (target_col %in% names(rem_data)) rem_data$classe_base <- as.character(rem_data[[target_col]])
      else if ("class" %in% names(rem_data)) rem_data$classe_base <- as.character(rem_data$class)
      else rem_data$classe_base <- as.character(rem_data[[1]])
      rem_data$Tipo <- "Removed"
    } else {
      rem_data <- orig[0, , drop = FALSE]
    }
    
    num_vars <- names(Filter(is.numeric, orig))
    num_vars <- setdiff(num_vars, c("SampleID", "classe_base", "Tipo", target_col, "class", "sampleclass", "sampleclass.."))
    
    common_cols <- intersect(names(orig), union(names(syn_data), names(rem_data)))
    df_all <- dplyr::bind_rows(
      orig[, common_cols, drop = FALSE],
      syn_data[, intersect(common_cols, names(syn_data)), drop = FALSE],
      rem_data[, intersect(common_cols, names(rem_data)), drop = FALSE]
    )
    df_all$SampleID <- seq_len(nrow(df_all))
    
    list(
      orig = orig,
      syn = syn_data,
      rem = rem_data,
      all = df_all,
      num_vars = num_vars,
      target_col = target_col,
      method = method_name
    )
  })

  # =========================================================================
  # 1. JENSEN-SHANNON DIVERGENCE (TABLE & PLOTS)
  # =========================================================================
  
  js_divergence <- function(x, y, bins = 30) {
    if (length(x) < 1 || length(y) < 1) return(NA)
    
    if (is.numeric(x)) {
      breaks <- pretty(c(x, y), n = bins)
      hist_x <- hist(x, breaks = breaks, plot = FALSE)$density
      hist_y <- hist(y, breaks = breaks, plot = FALSE)$density
    } else {
      x <- as.character(x)
      y <- as.character(y)
      levels_all <- union(unique(x), unique(y))
      hist_x <- table(factor(x, levels = levels_all))
      hist_y <- table(factor(y, levels = levels_all))
      hist_x <- as.numeric(hist_x)
      hist_y <- as.numeric(hist_y)
    }
    
    if (sum(hist_x) == 0 || sum(hist_y) == 0) return(NA)
    
    px <- hist_x / sum(hist_x)
    py <- hist_y / sum(hist_y)
    
    suppressWarnings(philentropy::distance(rbind(px, py), method = "jensen-shannon"))
  }
  
  js_divergence_data <- NULL  # Alias set below
  js_div_data <- reactive({
    info <- get_active_resampled_data()
    req(info)
    df_all <- info$all
    num_vars <- info$num_vars
    if (is.null(df_all) || length(num_vars) == 0) return(NULL)
    
    classes <- unique(df_all$classe_base[df_all$Tipo == "Original"])
    res <- data.frame()
    
    for (cl in classes) {
      df_o <- df_all %>% dplyr::filter(classe_base == cl & Tipo == "Original")
      df_syn <- df_all %>% dplyr::filter(classe_base == cl & Tipo == "Synthetic")
      df_rem <- df_all %>% dplyr::filter(classe_base == cl & Tipo == "Removed")
      
      df_comp <- df_o
      if (nrow(df_syn) > 0) df_comp <- dplyr::bind_rows(df_comp, df_syn)
      if (nrow(df_rem) > 0) {
        rem_keys <- intersect(names(df_comp), names(df_rem))
        df_comp <- dplyr::anti_join(df_comp, df_rem, by = rem_keys)
      }
      
      if (nrow(df_o) >= 1 && nrow(df_comp) >= 1) {
        for (v in num_vars) {
          x_orig <- df_o[[v]]
          x_comp <- df_comp[[v]]
          if (is.numeric(x_orig) && is.numeric(x_comp)) {
            val <- js_divergence(x_orig, x_comp)
            if (!is.na(val)) {
              res <- rbind(res, data.frame(
                Class = cl,
                Variable = v,
                Divergence = val,
                Compared_With = if (nrow(df_syn) > 0 && nrow(df_rem) > 0) "Synthetic & Removed"
                                else if (nrow(df_syn) > 0) "Synthetic"
                                else if (nrow(df_rem) > 0) "Removed"
                                else "Original",
                stringsAsFactors = FALSE
              ))
            }
          }
        }
      }
    }
    
    if (nrow(res) == 0) return(NULL)
    res$Class <- factor(res$Class, levels = unique(res$Class))
    res$Variable <- factor(res$Variable, levels = unique(res$Variable))
    return(res)
  })
  js_divergence_data <- js_div_data
  
  observe({
    df_js <- js_div_data()
    req(df_js)
    updateSelectInput(session, "classe_detalhe", choices = unique(df_js$Class))
    updateSelectInput(session, "variavel_detalhe", choices = unique(df_js$Variable))
  })
  
  output$js_divergence_plot <- renderPlotly({
    df_js <- js_div_data()
    req(df_js)
    
    if (is.null(df_js) || nrow(df_js) == 0) {
      return(plotly_empty(type = "scatter", mode = "markers") %>%
               layout(title = "No divergence calculated for selected classes"))
    }
    
    df_wide <- df_js %>%
      dplyr::select(Class, Variable, Divergence) %>%
      tidyr::pivot_wider(names_from = Class, values_from = Divergence)
    
    df_wide$Variable <- as.character(df_wide$Variable)
    classe_cols <- setdiff(names(df_wide), "Variable")
    if (length(classe_cols) == 0) {
      return(plotly_empty(type = "scatter", mode = "lines") %>%
               layout(title = "No divergence was calculated."))
    }
    
    variaveis <- df_wide$Variable
    n_classes <- length(classe_cols)
    cores <- RColorBrewer::brewer.pal(pmin(max(3, n_classes), 8), "Set1")
    
    plot <- plot_ly()
    for (i in seq_along(classe_cols)) {
      classe_nome <- classe_cols[i]
      if (!(classe_nome %in% names(df_wide))) next
      
      plot <- plot %>%
        add_trace(
          x = variaveis,
          y = df_wide[[classe_nome]],
          type = "scatter",
          mode = "lines+markers",
          name = classe_nome,
          line = list(width = 2),
          marker = list(size = 6),
          hoverinfo = "text",
          text = paste0(
            "<b>Class:</b> ", classe_nome,
            "<br><b>Variable:</b> ", variaveis,
            "<br><b>JS Divergence:</b> ", ifelse(is.na(df_wide[[classe_nome]]), "NA", round(as.numeric(df_wide[[classe_nome]]), 4))
          ),
          color = I(cores[(i - 1) %% length(cores) + 1])
        )
    }
    
    plot %>%
      layout(
        title = list(text = "Jensen-Shannon Divergence: Original vs Resampled", font = list(size = 18)),
        xaxis = list(title = "Variables"),
        yaxis = list(title = "Jensen-Shannon Divergence"),
        legend = list(title = list(text = "Class")),
        hovermode = "closest",
        margin = list(b = 100)
      )
  })
  
  output$js_distribution_plot <- renderPlotly({
    req(filedata(), input$classe_detalhe, input$variavel_detalhe)
    info <- get_active_resampled_data()
    req(info)
    df_all <- info$all
    
    cl <- input$classe_detalhe
    var <- input$variavel_detalhe
    
    sub_df <- df_all %>% dplyr::filter(classe_base == cl)
    if (nrow(sub_df) == 0 || !(var %in% names(sub_df))) {
      return(plotly_empty() %>% layout(title = "No data for selected class and variable."))
    }
    
    plot <- plot_ly()
    tipos_presentes <- unique(sub_df$Tipo)
    cores_map <- c("Original" = "#1f77b4", "Synthetic" = "#2ca02c", "Removed" = "#d62728")
    
    for (t in tipos_presentes) {
      vals <- sub_df[[var]][sub_df$Tipo == t]
      vals <- vals[!is.na(vals) & is.finite(vals)]
      if (length(vals) > 0) {
        col_t <- if (t %in% names(cores_map)) cores_map[[t]] else "#9467bd"
        plot <- plot %>% add_trace(
          x = vals,
          type = "histogram",
          name = paste0(cl, " (", t, ")"),
          opacity = 0.55,
          marker = list(color = col_t)
        )
      }
    }
    
    plot %>% layout(
      title = paste("Distribution Comparison — Class:", cl, "— Variable:", var),
      barmode = "overlay",
      xaxis = list(title = var),
      yaxis = list(title = "Sample Count"),
      legend = list(title = list(text = "Sample Type"))
    )
  })

  # =========================================================================
  # 2. GENERALIZED PROCRUSTES ANALYSIS & TEST
  # =========================================================================
  
  output$grafico_procrustes_multiclasse <- renderPlotly({
    info <- get_active_resampled_data()
    req(info)
    df_all <- info$all
    num_vars <- info$num_vars
    
    validate(need(length(num_vars) >= 2, "At least 2 numeric variables are required for Procrustes analysis."))
    
    classes_originais <- unique(df_all$classe_base[df_all$Tipo == "Original"])
    classes_comp <- unique(df_all$classe_base[df_all$Tipo %in% c("Synthetic", "Removed")])
    classes_validas <- intersect(classes_originais, classes_comp)
    
    validate(need(length(classes_validas) > 0, "No class has sufficient synthetic/removed samples to compare."))
    
    p <- plot_ly()
    plotted <- FALSE
    
    for (classe in classes_validas) {
      orig_sub <- subset(df_all, Tipo == "Original" & classe_base == classe)
      for (tipo_c in c("Synthetic", "Removed")) {
        comp_sub <- subset(df_all, Tipo == tipo_c & classe_base == classe)
        if (nrow(orig_sub) >= 2 && nrow(comp_sub) >= 2) {
          n <- min(nrow(orig_sub), nrow(comp_sub))
          valid_bool <- sapply(orig_sub[1:n, num_vars, drop = FALSE], function(x) !is.na(sd(x, na.rm=TRUE)) && sd(x, na.rm=TRUE) > 0) &
                        sapply(comp_sub[1:n, num_vars, drop = FALSE], function(x) !is.na(sd(x, na.rm=TRUE)) && sd(x, na.rm=TRUE) > 0)
          valid_bool[is.na(valid_bool)] <- FALSE
          vars_v <- num_vars[valid_bool]
          
          if (length(vars_v) >= 2) {
            X <- scale(orig_sub[1:n, vars_v, drop = FALSE])
            Y <- scale(comp_sub[1:n, vars_v, drop = FALSE])
            if (all(is.finite(X)) && all(is.finite(Y))) {
              proc <- vegan::procrustes(X, Y, scale = TRUE)
              X_df <- as.data.frame(proc$X[, 1:2])
              Y_df <- as.data.frame(proc$Yrot[, 1:2])
              names(X_df) <- names(Y_df) <- c("Dim1", "Dim2")
              X_df$ClassLeg <- paste(classe, "(Original)")
              Y_df$ClassLeg <- paste(classe, paste0("(", tipo_c, ")"))
              X_df$SampleID <- seq_len(nrow(X_df))
              Y_df$SampleID <- seq_len(nrow(Y_df))
              
              for (i in 1:n) {
                line_df <- data.frame(Dim1 = c(X_df$Dim1[i], Y_df$Dim1[i]), Dim2 = c(X_df$Dim2[i], Y_df$Dim2[i]))
                p <- add_trace(p, data = line_df, x = ~Dim1, y = ~Dim2, type = "scatter", mode = "lines",
                               line = list(color = "rgba(120,120,120,0.3)", width = 1), hoverinfo = "none", showlegend = FALSE)
              }
              p <- add_trace(p, data = X_df, x = ~Dim1, y = ~Dim2, type = "scatter", mode = "markers", marker = list(size = 8),
                             name = unique(X_df$ClassLeg), hoverinfo = "text", text = ~paste("Class:", ClassLeg, "<br>SampleID:", SampleID))
              p <- add_trace(p, data = Y_df, x = ~Dim1, y = ~Dim2, type = "scatter", mode = "markers", marker = list(size = 8, symbol = "circle-open"),
                             name = unique(Y_df$ClassLeg), hoverinfo = "text", text = ~paste("Class:", ClassLeg, "<br>SampleID:", SampleID))
              plotted <- TRUE
            }
          }
        }
      }
    }
    
    validate(need(plotted, "Insufficient variance or overlap to render Procrustes plots."))
    
    p %>% layout(
      title = "Generalized Procrustes Analysis by Class",
      xaxis = list(title = "Dimension 1"),
      yaxis = list(title = "Dimension 2"),
      legend = list(orientation = "v", x = 1, y = 1)
    )
  })

  output$procrustes_tabela_teste <- DT::renderDataTable({
    info <- get_active_resampled_data()
    req(info)
    df_all <- info$all
    num_vars <- info$num_vars
    
    if (is.null(df_all) || length(num_vars) < 2) return(datatable(data.frame()))
    
    classes_originais <- unique(df_all$classe_base[df_all$Tipo == "Original"])
    res_prot <- data.frame()
    
    for (classe in classes_originais) {
      orig_sub <- subset(df_all, Tipo == "Original" & classe_base == classe)
      for (tipo_c in c("Synthetic", "Removed")) {
        comp_sub <- subset(df_all, Tipo == tipo_c & classe_base == classe)
        if (nrow(orig_sub) >= 2 && nrow(comp_sub) >= 2) {
          n <- min(nrow(orig_sub), nrow(comp_sub))
          valid_bool <- sapply(orig_sub[1:n, num_vars, drop = FALSE], function(x) !is.na(sd(x, na.rm=TRUE)) && sd(x, na.rm=TRUE) > 0) &
                        sapply(comp_sub[1:n, num_vars, drop = FALSE], function(x) !is.na(sd(x, na.rm=TRUE)) && sd(x, na.rm=TRUE) > 0)
          valid_bool[is.na(valid_bool)] <- FALSE
          vars_v <- num_vars[valid_bool]
          
          if (length(vars_v) >= 2) {
            X <- scale(orig_sub[1:n, vars_v, drop = FALSE])
            Y <- scale(comp_sub[1:n, vars_v, drop = FALSE])
            if (all(is.finite(X)) && all(is.finite(Y))) {
              try({
                test <- vegan::protest(X, Y, permutations = 499)
                res_prot <- rbind(res_prot, data.frame(
                  Class = classe,
                  Comparison = paste("Original vs", tipo_c),
                  Procrustes_SS = signif(test$ss, 4),
                  Correlation_r = signif(test$t0, 4),
                  p_value = signif(test$signif, 4),
                  stringsAsFactors = FALSE
                ))
              }, silent = TRUE)
            }
          }
        }
      }
    }
    
    if (nrow(res_prot) == 0) return(datatable(data.frame()))
    DT::datatable(res_prot, rownames = FALSE, options = list(pageLength = 10, dom = 'tip'))
  })

    # =========================================================================
  # 3. MAHALANOBIS DISTANCE PLOT BY CLASS (BAR CHART WITH CRITICAL LIMIT)
  # =========================================================================
  
  output$grafico_mahalanobis_por_classe <- renderPlotly({
    info <- get_active_resampled_data()
    req(info)
    df_all <- info$all
    num_vars <- info$num_vars
    
    if (is.null(df_all) || length(num_vars) < 2) {
      return(plotly_empty() %>% layout(title = "At least 2 numeric variables required for Mahalanobis Distance."))
    }
    
    # Filter ONLY classes that were synthesized / resampled
    classes_resampled <- unique(df_all$classe_base[df_all$Tipo %in% c("Synthetic", "Removed")])
    if (length(classes_resampled) == 0) {
      return(plotly_empty() %>% layout(title = "No synthetic or resampled samples available. Run a sampling method first."))
    }
    
    bar_data <- data.frame()
    
    for (cl in classes_resampled) {
      df_orig_cl <- df_all %>% dplyr::filter(classe_base == cl & Tipo == "Original")
      df_syn_cl <- df_all %>% dplyr::filter(classe_base == cl & Tipo %in% c("Synthetic", "Removed"))
      
      n1 <- nrow(df_orig_cl)
      n2 <- nrow(df_syn_cl)
      
      if (n1 >= 2 && n2 >= 1) {
        valid_bool <- sapply(df_orig_cl[, num_vars, drop = FALSE], function(x) !is.na(sd(x, na.rm=TRUE)) && sd(x, na.rm=TRUE) > 0 && all(is.finite(x)))
        valid_bool[is.na(valid_bool)] <- FALSE
        vars_v <- num_vars[valid_bool]
        p_dim <- length(vars_v)
        
        if (p_dim >= 2) {
          X_orig <- as.matrix(df_orig_cl[, vars_v, drop = FALSE])
          X_syn <- as.matrix(df_syn_cl[, vars_v, drop = FALSE])
          
          m_orig <- colMeans(X_orig, na.rm = TRUE)
          m_syn <- colMeans(X_syn, na.rm = TRUE)
          diff_m <- m_syn - m_orig
          
          # Pooled covariance matrix
          s1 <- if (n1 > 1) cov(X_orig) else diag(1, p_dim)
          s2 <- if (n2 > 1) cov(X_syn) else s1
          
          s_pooled <- ((n1 - 1) * s1 + (n2 - 1) * s2) / max(1, (n1 + n2 - 2))
          if (rcond(s_pooled) < 1e-6 || is.na(rcond(s_pooled))) {
            s_pooled <- s_pooled + diag(1e-4 * mean(diag(s_pooled)), p_dim)
          }
          
          # Mahalanobis Distance between centroids
          d2 <- tryCatch(as.numeric(t(diff_m) %*% solve(s_pooled) %*% diff_m), error = function(e) NA)
          
          if (!is.na(d2) && d2 >= 0) {
            d_m <- sqrt(d2)
            
            # Critical threshold from Hotelling T2 / F distribution (alpha = 0.05)
            alpha_sig <- 0.05
            df1 <- p_dim
            df2 <- n1 + n2 - p_dim - 1
            
            if (df2 > 0) {
              f_crit <- qf(1 - alpha_sig, df1, df2)
              t2_crit <- (p_dim * (n1 + n2 - 2) / df2) * f_crit
              d_crit <- sqrt(((n1 + n2) / (n1 * n2)) * t2_crit)
              f_val <- (df2 / (p_dim * (n1 + n2 - 2))) * ((n1 * n2) / (n1 + n2)) * d2
              p_val <- 1 - pf(f_val, df1, df2)
            } else {
              chi_crit <- qchisq(1 - alpha_sig, df = p_dim)
              d_crit <- sqrt(((n1 + n2) / (n1 * n2)) * chi_crit)
              p_val <- 1 - pchisq(((n1 * n2) / (n1 + n2)) * d2, df = p_dim)
            }
            
            is_equiv <- (!is.na(d_m) && !is.na(d_crit) && d_m <= d_crit)
            status_lbl <- if (is_equiv) "Preserved (p > 0.05)" else "Significantly Shifted (p <= 0.05)"
            bar_color <- if (is_equiv) "#2ca02c" else "#d62728"
            
            bar_data <- rbind(bar_data, data.frame(
              Class = cl,
              Distance = round(d_m, 4),
              Critical_Limit = round(d_crit, 4),
              p_value = if (!is.na(p_val)) round(p_val, 4) else NA,
              Status = status_lbl,
              Color = bar_color,
              stringsAsFactors = FALSE
            ))
          }
        }
      }
    }
    
    if (nrow(bar_data) == 0) {
      return(plotly_empty() %>% layout(title = "Insufficient variance or samples to compute Mahalanobis Distance."))
    }
    
    bar_data$Class <- factor(bar_data$Class, levels = unique(bar_data$Class))
    
    p_plot <- plot_ly(data = bar_data) %>%
      add_bars(
        x = ~Class,
        y = ~Distance,
        name = "Mahalanobis Distance (D_M)",
        marker = list(
          color = ~Color,
          line = list(color = "#333333", width = 1.5)
        ),
        text = ~paste0(
          "<b>Class:</b> ", Class,
          "<br><b>Mahalanobis Distance (D_M):</b> ", Distance,
          "<br><b>Critical Limit (D_crit):</b> ", Critical_Limit,
          "<br><b>p-value:</b> ", ifelse(is.na(p_value), "N/A", p_value),
          "<br><b>Status:</b> ", Status
        ),
        hoverinfo = "text"
      ) %>%
      add_trace(
        x = ~Class,
        y = ~Critical_Limit,
        type = "scatter",
        mode = "lines+markers",
        name = "Critical Limit (alpha = 0.05)",
        line = list(color = "#d62728", width = 3, dash = "dash"),
        marker = list(symbol = "diamond", size = 10, color = "#d62728", line = list(color = "#000000", width = 1)),
        text = ~paste0(
          "<b>Class:</b> ", Class,
          "<br><b>Critical Threshold (D_crit):</b> ", Critical_Limit,
          "<br><i>Threshold for statistical significance (alpha = 0.05)</i>"
        ),
        hoverinfo = "text"
      ) %>%
      layout(
        title = list(text = "Mahalanobis Distance: Original vs Synthetic Centroids (with Critical Threshold)", font = list(size = 16)),
        xaxis = list(title = "Synthesized Class", tickfont = list(size = 13)),
        yaxis = list(title = "Mahalanobis Distance (D_M)", tickfont = list(size = 12), zeroline = TRUE),
        legend = list(
          orientation = "v",
          x = 1.02,
          xanchor = "left",
          y = 1,
          yanchor = "top",
          font = list(size = 12)
        ),
        margin = list(t = 60, b = 60, l = 60, r = 180)
      )
    
    p_plot
  })

  # =========================================================================
  # 4. KOLMOGOROV-SMIRNOV TEST TABLE
  # =========================================================================
  
  output$ks_por_classe <- DT::renderDataTable({
    info <- get_active_resampled_data()
    req(info)
    df_all <- info$all
    num_vars <- info$num_vars
    
    if (is.null(df_all) || length(num_vars) == 0) return(datatable(data.frame()))
    
    classes_orig <- unique(df_all$classe_base[df_all$Tipo == "Original"])
    ks_results <- data.frame()
    
    for (cl in classes_orig) {
      df_orig_cl <- df_all %>% dplyr::filter(classe_base == cl & Tipo == "Original")
      
      for (tipo_c in c("Synthetic", "Removed")) {
        df_comp_cl <- df_all %>% dplyr::filter(classe_base == cl & Tipo == tipo_c)
        if (nrow(df_orig_cl) >= 2 && nrow(df_comp_cl) >= 2) {
          for (var in num_vars) {
            x_o <- df_orig_cl[[var]]
            x_c <- df_comp_cl[[var]]
            x_o <- x_o[!is.na(x_o) & is.finite(x_o)]
            x_c <- x_c[!is.na(x_c) & is.finite(x_c)]
            
            if (length(x_o) >= 2 && length(x_c) >= 2) {
              try({
                ks_res <- suppressWarnings(ks.test(x_o, x_c))
                p_val <- as.numeric(ks_res$p.value)
                d_stat <- as.numeric(ks_res$statistic)
                status_txt <- if (!is.na(p_val) && p_val > 0.05) "Distributions Equal (p > 0.05)" else "Distributions Differ (p <= 0.05)"
                
                ks_results <- rbind(ks_results, data.frame(
                  Class = cl,
                  Comparison = paste("Original vs", tipo_c),
                  Variable = var,
                  D_Statistic = round(d_stat, 4),
                  p_value = round(p_val, 4),
                  Conclusion = status_txt,
                  stringsAsFactors = FALSE
                ))
              }, silent = TRUE)
            }
          }
        }
      }
    }
    
    if (nrow(ks_results) == 0) return(datatable(data.frame()))
    DT::datatable(ks_results, rownames = FALSE, options = list(pageLength = 10, dom = 'tip', scrollX = TRUE))
  })

  # =========================================================================
  # 5. MULTIVARIATE NORMALITY, HOTELLING'S T^2 & PERMANOVA TESTS
  # =========================================================================
  
  observe({
    info <- get_active_resampled_data()
    req(info)
    dados <- info$all
    num_vars <- info$num_vars
    
    classes_originais <- unique(dados$classe_base[dados$Tipo == "Original"])
    if (length(classes_originais) == 0 || length(num_vars) < 2) {
      output$normalidade_table <- DT::renderDataTable({ datatable(data.frame()) })
      output$hotelling_table <- DT::renderDataTable({ datatable(data.frame()) })
      output$permanova_table <- DT::renderDataTable({ datatable(data.frame()) })
      return()
    }
    
    # --- MULTIVARIATE NORMALITY TEST BY CLASS ---
    resultados_normalidade <- lapply(classes_originais, function(classe) {
      idx <- which(dados$classe_base == classe & dados$Tipo == "Original")
      if (length(idx) == 0) idx <- which(dados$classe_base == classe)
      subset_classe <- dados[idx, num_vars, drop = FALSE]
      
      valid_bool <- sapply(subset_classe, function(x) {
        is.numeric(x) && !is.na(sd(x, na.rm = TRUE)) && sd(x, na.rm = TRUE) > 0 && all(is.finite(x))
      })
      valid_bool[is.na(valid_bool)] <- FALSE
      vars_validas <- num_vars[valid_bool]
      p_dim <- length(vars_validas)
      n_obs <- nrow(subset_classe)
      
      if (p_dim < 2 || n_obs <= p_dim) {
        return(data.frame(
          Class = classe,
          Statistic_HZ = NA,
          p_value_HZ = NA,
          Status_HZ = paste0("Insufficient sample size (n=", n_obs, " <= p=", p_dim, ")"),
          Statistic_Royston = NA,
          p_value_Royston = NA,
          Status_Royston = paste0("Insufficient sample size (n=", n_obs, " <= p=", p_dim, ")"),
          stringsAsFactors = FALSE
        ))
      }
      
      X <- as.data.frame(subset_classe[, vars_validas, drop = FALSE])
      rownames(X) <- NULL
      
      hz_val <- p_hz <- NA; status_hz <- "Error"
      roy_val <- p_roy <- NA; status_roy <- "Error"
      
      # Henze-Zirkler Test
      tryCatch({
        r_hz <- suppressWarnings(MVN::mvn(data = X, mvn_test = "hz", descriptives = FALSE))
        df_hz <- if (!is.null(r_hz$multivariate_normality)) r_hz$multivariate_normality else r_hz$multivariateNormality
        if (!is.null(df_hz) && nrow(df_hz) >= 1) {
          hz_val <- as.numeric(as.character(df_hz$Statistic[1]))
          p_col_name <- grep('p', names(df_hz), ignore.case = TRUE, value = TRUE)[1]
          p_raw <- as.character(df_hz[[p_col_name]][1])
          p_hz <- if (grepl('<', p_raw)) 0.0001 else as.numeric(p_raw)
          status_hz <- if (!is.na(p_hz) && p_hz > 0.05) "Normality Met" else "Normality Violated"
        }
      }, error = function(e) {
        status_hz <<- paste("Note:", e$message)
      })
      
      # Royston Test
      tryCatch({
        r_roy <- suppressWarnings(MVN::mvn(data = X, mvn_test = "royston", descriptives = FALSE))
        df_roy <- if (!is.null(r_roy$multivariate_normality)) r_roy$multivariate_normality else r_roy$multivariateNormality
        if (!is.null(df_roy) && nrow(df_roy) >= 1) {
          roy_val <- as.numeric(as.character(df_roy$Statistic[1]))
          p_col_name <- grep('p', names(df_roy), ignore.case = TRUE, value = TRUE)[1]
          p_raw <- as.character(df_roy[[p_col_name]][1])
          p_roy <- if (grepl('<', p_raw)) 0.0001 else as.numeric(p_raw)
          status_roy <- if (!is.na(p_roy) && p_roy > 0.05) "Normality Met" else "Normality Violated"
        }
      }, error = function(e) {
        status_roy <<- paste("Note:", e$message)
      })
      
      data.frame(
        Class = classe,
        Statistic_HZ = if (!is.na(hz_val)) round(hz_val, 4) else NA,
        p_value_HZ = if (!is.na(p_hz)) round(p_hz, 4) else NA,
        Status_HZ = status_hz,
        Statistic_Royston = if (!is.na(roy_val)) round(roy_val, 4) else NA,
        p_value_Royston = if (!is.na(p_roy)) round(p_roy, 4) else NA,
        Status_Royston = status_roy,
        stringsAsFactors = FALSE
      )
    })
    
    df_normalidade <- do.call(rbind, resultados_normalidade)
    output$normalidade_table <- DT::renderDataTable({
      DT::datatable(df_normalidade, rownames = FALSE, options = list(pageLength = 10, dom = 'tip'))
    })
    
    # --- HOTELLING'S T^2 TEST BY CLASS ---
    resultados_hotelling <- lapply(classes_originais, function(classe) {
      orig <- subset(dados, Tipo == "Original" & classe_base == classe)
      comp <- subset(dados, Tipo %in% c("Synthetic", "Removed") & classe_base == classe)
      
      n1 <- nrow(orig)
      n2 <- nrow(comp)
      
      if (n1 < 2 || n2 < 1) {
        return(data.frame(
          Class = classe,
          Hotelling_T2 = NA,
          F_Statistic = NA,
          df1 = NA,
          df2 = NA,
          p_value = NA,
          Conclusion = "No synthetic samples for this class",
          stringsAsFactors = FALSE
        ))
      }
      
      valid_bool <- sapply(orig[, num_vars, drop = FALSE], function(x) {
        is.numeric(x) && !is.na(sd(x, na.rm = TRUE)) && sd(x, na.rm = TRUE) > 0 && all(is.finite(x))
      }) & sapply(comp[, num_vars, drop = FALSE], function(x) {
        is.numeric(x) && !is.na(sd(x, na.rm = TRUE)) && sd(x, na.rm = TRUE) > 0 && all(is.finite(x))
      })
      valid_bool[is.na(valid_bool)] <- FALSE
      vars_validas <- num_vars[valid_bool]
      p_dim <- length(vars_validas)
      
      if (p_dim < 2) {
        return(data.frame(
          Class = classe,
          Hotelling_T2 = NA,
          F_Statistic = NA,
          df1 = NA,
          df2 = NA,
          p_value = NA,
          Conclusion = "Insufficient valid numeric variables",
          stringsAsFactors = FALSE
        ))
      }
      
      X_orig <- as.data.frame(orig[, vars_validas, drop = FALSE])
      X_comp <- as.data.frame(comp[, vars_validas, drop = FALSE])
      rownames(X_orig) <- NULL
      rownames(X_comp) <- NULL
      
      t2_val <- f_val <- p_val <- df_num <- df_den <- NA
      conc_txt <- "Success"
      
      tryCatch({
        ht <- Hotelling::hotelling.test(X_orig, X_comp)
        t2_val <- round(as.numeric(ht$stats$statistic), 4)
        df_num <- as.numeric(ht$stats$df[1])
        df_den <- as.numeric(ht$stats$df[2])
        p_val <- round(as.numeric(ht$pval), 4)
        
        # Calculate F-statistic
        if (!is.na(df_den) && df_den > 0) {
          f_val <- round((df_den / (p_dim * (n1 + n2 - 2))) * t2_val, 4)
        }
        
        conc_txt <- if (!is.na(p_val) && p_val > 0.05) "Mean Vectors Equal (p > 0.05)" else "Mean Vectors Differ (p <= 0.05)"
      }, error = function(e) {
        err_msg <- e$message
        if (grepl("computacionalmente singular", err_msg, ignore.case = TRUE)) {
          err_msg <- sub(".*computacionalmente singular:?\\s*", "system is computationally singular: ", err_msg, ignore.case = TRUE)
          err_msg <- sub("condi[cç][aã]o rec[ií]proca n[uú]mero", "reciprocal condition number", err_msg, ignore.case = TRUE)
        }
        conc_txt <<- paste("Note:", err_msg)
      })
      
      data.frame(
        Class = classe,
        Hotelling_T2 = t2_val,
        F_Statistic = f_val,
        df1 = df_num,
        df2 = df_den,
        p_value = p_val,
        Conclusion = conc_txt,
        stringsAsFactors = FALSE
      )
    })
    
    df_hotelling <- do.call(rbind, resultados_hotelling)
    output$hotelling_table <- DT::renderDataTable({
      DT::datatable(df_hotelling, rownames = FALSE, options = list(pageLength = 10, dom = 'tip'))
    })
    
    # --- PERMANOVA MULTIVARIATE EQUALITY TEST ---
    tipos_comp <- unique(dados$Tipo[dados$Tipo != "Original"])
    if (length(tipos_comp) == 0) tipos_comp <- "Synthetic"
    
    res_perm <- data.frame()
    for (classe in classes_originais) {
      for (tipo in tipos_comp) {
        sub_d <- subset(dados, classe_base == classe & Tipo %in% c("Original", tipo))
        if (length(unique(sub_d$Tipo)) == 2 && min(table(sub_d$Tipo)) >= 2) {
          valid_bool <- sapply(sub_d[, num_vars, drop = FALSE], function(x) {
            is.numeric(x) && !is.na(sd(x, na.rm = TRUE)) && sd(x, na.rm = TRUE) > 0 && all(is.finite(x))
          })
          valid_bool[is.na(valid_bool)] <- FALSE
          vars_v <- num_vars[valid_bool]
          
          if (length(vars_v) >= 2) {
            try({
              X_mat <- scale(sub_d[, vars_v, drop = FALSE])
              perm_res <- vegan::adonis2(X_mat ~ Tipo, data = sub_d, permutations = 499, method = "euclidean")
              res_perm <- rbind(res_perm, data.frame(
                Class = classe,
                Comparison = paste("Original vs", tipo),
                F_Model = signif(perm_res$F[1], 4),
                R2 = signif(perm_res$R2[1], 4),
                p_value = signif(perm_res$`Pr(>F)`[1], 4),
                Conclusion = if (!is.na(perm_res$`Pr(>F)`[1]) && perm_res$`Pr(>F)`[1] > 0.05) "Equal Centers/Dispersions (p > 0.05)" else "Significant Difference (p <= 0.05)",
                stringsAsFactors = FALSE
              ))
            }, silent = TRUE)
          }
        }
      }
    }
    
    output$permanova_table <- DT::renderDataTable({
      DT::datatable(res_perm, rownames = FALSE, options = list(pageLength = 10, dom = 'tip'))
    })
  })

  # =========================================================================
  # 6. PCA SCORE BOXPLOT
  # =========================================================================
  
  output$boxplot_scores <- renderPlotly({
    info <- get_active_resampled_data()
    req(info)
    df_all <- info$all
    num_vars <- info$num_vars
    
    if (is.null(df_all) || length(num_vars) < 2) {
      return(plotly_empty() %>% layout(title = "At least 2 numeric variables are required for PCA scores boxplot."))
    }
    
    valid_bool <- sapply(df_all[, num_vars, drop = FALSE], function(x) {
      is.numeric(x) && !is.na(sd(x, na.rm = TRUE)) && sd(x, na.rm = TRUE) > 0 && all(is.finite(x))
    })
    valid_bool[is.na(valid_bool)] <- FALSE
    vars_validas <- num_vars[valid_bool]
    
    if (length(vars_validas) < 2) {
      return(plotly_empty() %>% layout(title = "Insufficient numeric variables with non-zero variance."))
    }
    
    X_mat <- df_all[, vars_validas, drop = FALSE]
    pca_fit <- tryCatch(prcomp(X_mat, center = TRUE, scale. = TRUE), error = function(e) NULL)
    if (is.null(pca_fit)) {
      return(plotly_empty() %>% layout(title = "PCA computation failed due to collinearity or scale."))
    }
    
    scores_df <- as.data.frame(pca_fit$x)
    scores_df$ClassGroup <- paste0(df_all$classe_base, " (", df_all$Tipo, ")")
    scores_df$SampleID <- df_all$SampleID
    
    pcs_all <- colnames(pca_fit$x)
    var_exp <- summary(pca_fit)$importance["Proportion of Variance", ]
    pcs_labels <- sprintf("%s (%.1f%%)", pcs_all, 100 * var_exp)
    label_map <- setNames(pcs_labels, pcs_all)
    
    selected_input <- input$pcs_to_show
    if (is.null(selected_input) || length(selected_input) == 0 || "ALL" %in% selected_input || "All PCs" %in% selected_input) {
      selected_pcs <- pcs_all[1:min(length(pcs_all), 4)]
    } else {
      selected_pcs <- intersect(selected_input, pcs_all)
      if (length(selected_pcs) == 0) selected_pcs <- pcs_all[1:min(length(pcs_all), 4)]
    }
    
    scores_sub <- scores_df[, c(selected_pcs, "ClassGroup"), drop = FALSE]
    names(scores_sub)[1:length(selected_pcs)] <- label_map[selected_pcs]
    
    melted <- reshape2::melt(scores_sub, id.vars = "ClassGroup", variable.name = "PC", value.name = "Score")
    melted$PC <- factor(melted$PC, levels = label_map[selected_pcs])
    
    plot_ly(
      data = melted,
      x = ~PC,
      y = ~Score,
      color = ~ClassGroup,
      type = "box",
      boxpoints = "outliers"
    ) %>%
      layout(
        title = "PCA Score Distributions (Original vs Resampled)",
        xaxis = list(title = "Principal Components"),
        yaxis = list(title = "Score Values"),
        boxmode = "group"
      )
  })

  # =========================================================================
  # 7. VARIANCE TESTS (LEVENE & FLIGNER-KILLEEN)
  # =========================================================================
  
  observeEvent(input$run_variance_test, {
    info <- get_active_resampled_data()
    req(info)
    df_all <- info$all
    num_vars <- info$num_vars
    
    if (is.null(df_all) || length(num_vars) == 0) {
      output$variance_test_results <- renderPrint({ cat("No numeric variables available for variance tests.
") })
      return()
    }
    
    df_orig <- df_all %>% dplyr::filter(Tipo == "Original")
    df_comp <- df_all %>% dplyr::filter(Tipo %in% c("Synthetic", "Removed"))
    
    if (nrow(df_comp) == 0) {
      test_data <- df_orig
      group_col <- "classe_base"
    } else {
      test_data <- dplyr::bind_rows(df_orig, df_comp)
      group_col <- "Tipo"
    }
    
    test_type <- input$variance_test
    if (is.null(test_type)) test_type <- "Levene's Test"
    
    results <- lapply(num_vars, function(col) {
      x_vals <- test_data[[col]]
      g_vals <- as.factor(test_data[[group_col]])
      
      valid_idx <- !is.na(x_vals) & is.finite(x_vals) & !is.na(g_vals)
      x_vals <- x_vals[valid_idx]
      g_vals <- g_vals[valid_idx]
      
      if (length(unique(g_vals)) < 2 || length(x_vals) < 4) {
        return(data.frame(Variable = col, Test = test_type, Statistic = NA, P_Value = NA, Conclusion = "Insufficient data", stringsAsFactors = FALSE))
      }
      
      p_val <- stat_val <- NA
      status_msg <- "Calculation Error"
      
      if (test_type == "Levene's Test") {
        try({
          df_tmp <- data.frame(value = x_vals, group = g_vals)
          lev <- car::leveneTest(value ~ group, data = df_tmp)
          stat_val <- as.numeric(lev$`F value`[1])
          p_val <- as.numeric(lev$`Pr(>F)`[1])
          status_msg <- if (!is.na(p_val) && p_val > 0.05) "Equal Variances (p > 0.05)" else "Unequal Variances (p <= 0.05)"
        }, silent = TRUE)
      } else if (test_type == "Fligner-Killeen Test") {
        try({
          fk <- fligner.test(x_vals, g_vals)
          stat_val <- as.numeric(fk$statistic)
          p_val <- as.numeric(fk$p.value)
          status_msg <- if (!is.na(p_val) && p_val > 0.05) "Equal Variances (p > 0.05)" else "Unequal Variances (p <= 0.05)"
        }, silent = TRUE)
      }
      
      data.frame(
        Variable = col,
        Test = test_type,
        Statistic = ifelse(is.na(stat_val), NA, round(stat_val, 4)),
        P_Value = ifelse(is.na(p_val), NA, round(p_val, 4)),
        Conclusion = status_msg,
        stringsAsFactors = FALSE
      )
    })
    
    res_df <- do.call(rbind, results)
    output$variance_test_results <- renderPrint({
      print(res_df, row.names = FALSE)
    })
  })


