  observeEvent(input$confirmSMOTE, {
    req(filedata(), SMOTE_Data())
    original <- as.data.frame(filedata())
    synthetic <- SMOTE_Data()$syn_data
    
    target_col <- input$target
    orig_class_col <- if (!is.null(target_col) && target_col %in% names(original)) target_col
                      else if ("class" %in% names(original)) "class"
                      else if ("sampleclass" %in% names(original)) "sampleclass"
                      else names(original)[1]
    
    orig_labels <- as.character(original[[orig_class_col]])
    original$sampleclass.. <- paste0(orig_labels, " (Original)")
    
    if (!is.null(synthetic) && nrow(synthetic) > 0) {
      syn_col <- if ("class" %in% names(synthetic)) "class" else if (!is.null(target_col) && target_col %in% names(synthetic)) target_col else orig_class_col
      synthetic$sampleclass.. <- paste0(as.character(synthetic[[syn_col]]), " (Synthetic)")
    } else {
      synthetic <- NULL
    }
    
    confirmed_all <- dplyr::bind_rows(original, synthetic)
    combined_data_final(confirmed_all)
    
    confirmed_numerics <- confirmed_all %>% dplyr::select(where(is.numeric))
    if ("sampleclass.." %in% names(confirmed_numerics)) confirmed_numerics <- confirmed_numerics %>% dplyr::select(-sampleclass..)
    
    output$preview1 <- renderDT({ req(confirmed_all); datatable(confirmed_numerics, options = list(scrollX = TRUE)) })
    output$datasummary <- renderPrint({ req(confirmed_all); psych::describe(confirmed_numerics) })
    output$summary <- renderDT({ req(confirmed_all); skimr::skim(confirmed_numerics) })
    output$barplot <- renderPlotly({
      req(confirmed_all)
      df <- confirmed_all[!is.na(confirmed_all$sampleclass..), ]
      class_freq <- df %>% dplyr::count(sampleclass..) %>% dplyr::rename(Class = sampleclass.., Frequency = n)
      num_c <- max(3, nrow(class_freq))
      cols <- RColorBrewer::brewer.pal(min(9, num_c), "Set1")
      plot_ly(data = class_freq, x = ~Class, y = ~Frequency, type = "bar", color = ~Class, colors = cols,
              text = ~Frequency, textposition = 'outside') %>%
        layout(title = "Class Frequency (Original vs Synthetic)", xaxis = list(title = "Class"), yaxis = list(title = "Frequency"), showlegend = TRUE)
    })
    updateSelectizeInput(session, "removedatarow", choices = rownames(confirmed_all), server = TRUE)
    updateSelectizeInput(session, "removedatacol", choices = names(confirmed_all), server = TRUE)
    showNotification("SMOTE synthetic dataset successfully confirmed and updated!", type = "message", duration = 5)
  })

