      rem_col <- if ("class" %in% names(removed)) "class" else if (!is.null(target_col) && target_col %in% names(removed)) target_col else orig_class_col
      removed$sampleclass.. <- paste0(as.character(removed[[rem_col]]), " (Removed)")
    } else {
      removed <- NULL
    }
    
    confirmed_all <- dplyr::bind_rows(original, removed)
    confirmed_clean <- if (!is.null(removed)) dplyr::anti_join(original, removed, by = intersect(names(original), names(removed))) else original
    combined_data_final(confirmed_clean)
    
    confirmed_numerics <- confirmed_all %>% dplyr::select(where(is.numeric))
    if ("sampleclass.." %in% names(confirmed_numerics)) confirmed_numerics <- confirmed_numerics %>% dplyr::select(-sampleclass..)
    
    output$preview1 <- renderDT({ req(confirmed_all); datatable(confirmed_numerics, options = list(scrollX = TRUE)) })
    output$datasummary <- renderPrint({ req(confirmed_all); psych::describe(confirmed_numerics) })
    output$summary <- renderDT({ req(confirmed_all); skimr::skim(confirmed_numerics) })
    output$barplot <- renderPlotly({
      req(confirmed_all)
      df <- confirmed_all[!is.na(confirmed_all$sampleclass..), ]
      class_freq <- df %>% dplyr::count(sampleclass..) %>% dplyr::rename(Class = sampleclass.., Frequency = n)
      num_c <- max(3, nrow(class_freq))
      cols <- RColorBrewer::brewer.pal(min(9, num_c), "Set1")
      plot_ly(data = class_freq, x = ~Class, y = ~Frequency, type = "bar", color = ~Class, colors = cols,
              text = ~Frequency, textposition = 'outside') %>%
        layout(title = "Class Frequency (Original vs Resampled)", xaxis = list(title = "Class"), yaxis = list(title = "Frequency"), showlegend = TRUE)
    })
    updateSelectizeInput(session, "removedatarow", choices = rownames(confirmed_all), server = TRUE)
    updateSelectizeInput(session, "removedatacol", choices = names(confirmed_all), server = TRUE)
    showNotification("ENN resampled dataset successfully confirmed and updated!", type = "message", duration = 5)
  })

